async function api<T>(path:string,body?:unknown,method="POST"):Promise<T>{
 const response=await fetch(path,body===undefined?{cache:"no-store"}:{method,headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});
 const data=await response.json() as {code?:string;message?:string;error?:string|{message?:string}};
 if(!response.ok){const error=new Error(typeof data.error==="string"?data.error:data.error?.message??data.message??"The town could not complete that action.");Object.assign(error,{code:data.code,status:response.status});throw error;}
 return data as T;
}
