function taskFor(state:CozyWorldState){const dreamer=state.npcs.find(npc=>npc.id==="wren")?.name??"Wren";if(state.mind)return{title:state.mind.plan?.summary??`A little room for ${dreamer}’s own ideas.`,hint:`Meet ${dreamer}, share an idea, or tend your corner of the village.`,step:-1};if(state.emergence){const group=state.emergence.institutions.at(-1),plan=state.emergence.proposals.at(-1);return{title:group?group.name:plan?plan.name:"A town with room for its own ideas.",hint:group?"Follow the group’s choices and physical preparations in the journal.":plan?"A neighbor has a shared plan. Read the replies in the journal.":"Tend the garden, explore, and let your neighbors notice their own day.",step:-1};}if(state.festival.phase==="complete")return{title:"A little celebration, made together.",hint:"Your rules and their consequences are saved.",step:5};
 if(state.rules.organizer==="villagers")return{title:"Let the neighbors find their own way.",hint:"Follow their preparations in the town journal.",step:4};
 if(state.player.gifts>0)return{title:"What if the town planned the festival?",hint:"Open Town rules and change who organizes it.",step:3};
 if(state.player.harvests>0)return{title:"Good things are better shared.",hint:"Give a little wheat to Ada, Mara or Wren.",step:2};
 if(state.plots.some(p=>p.phase==="ripe"))return{title:"Your first harvest is ready.",hint:"Choose Harvest and click the golden wheat.",step:1};
 if(state.plots.some(p=>p.phase==="growing"))return{title:"A little patience. A little sunshine.",hint:"Explore, meet a neighbor, or sit and wait.",step:1};
 if(state.plots.some(p=>p.phase==="planted"))return{title:"Give your seeds a drink.",hint:"Choose Water, then click a planted plot.",step:0};
 return{title:"Start with one small seed.",hint:"Choose Plant, then click an empty garden plot.",step:0};}

